    "code_snippet": "func (s *Service) streamDataColumnBatch(ctx context.Context, batch blockBatch, quota uint64, wantedDataColumnIndices []uint64, stream libp2pcore.Stream) (uint64, error) {\n  if quota == 0 { return 0, nil }\n  for _, block := range batch.canonical() {\n    blockRoot := block.Root()\n    verifiedRODataColumns, err := s.cfg.dataColumnStorage.Get(blockRoot, wantedDataColumnIndices)\n    if err != nil { ... return quota, err }\n    for _, verifiedRODataColumn := range verifiedRODataColumns {\n      sidecar := verifiedRODataColumn.DataColumnSidecar\n      SetStreamWriteDeadline(stream, defaultWriteDuration)\n      if err := WriteDataColumnSidecarChunk(stream, ...); err != nil { ... return quota, err }\n      s.rateLimiter.add(stream, rateLimitingAmount)\n      quota -= 1\n      if quota == 0 { return 0, nil }  // EARLY EXIT MID-BLOCK\n    }\n  }\n  return quota, nil\n}",
